// Viewer for one Vivado RTL schematic page (generated by docs/gen_export_schematics_site.py).
// window.SCHEM = {module, insts: [{name, type, box, at, page}], nets: [{bus, pins, taps}],
//                 chain: [[instance, module], ...] (outermost first), ups: [{at, to, frame}],
//                 util: post-synthesis utilization of this instance or null (see the generator)}
// pins are [instance ("" = this module's port), pin, "in"|"out", x, y]; ups are the "−" icons
// of the enclosing frames, each going back to the module that contains that frame.
//
// Deep links: <module>.html#focus=<instance>.  Inside the site's iframe it talks to the
// parent with postMessage: sends {src:"schem", type:"ready"|"descend"|"ascend"}, accepts
// {type:"theme", theme} and {type:"focus", inst}.
(function () {
    "use strict";
    var NS = "http://www.w3.org/2000/svg";
    var D = window.SCHEM;
    var svg = document.getElementById("schem");
    var framed = window.parent !== window;
    var root = document.documentElement;
    if (framed) root.classList.add("framed");

    function post(msg) {
        if (framed) { msg.src = "schem"; window.parent.postMessage(msg, "*"); }
    }

    // ---- overlays: hit copies of every wire, hotspots on openable instances ----
    var content = svg.querySelector("g");
    var netPaths = new Map();
    var hits = document.createElementNS(NS, "g");
    svg.querySelectorAll("path[data-n]").forEach(function (p) {
        var n = +p.getAttribute("data-n");
        if (!netPaths.has(n)) netPaths.set(n, []);
        netPaths.get(n).push(p);
        var h = document.createElementNS(NS, "path");
        h.setAttribute("d", p.getAttribute("d"));
        h.setAttribute("class", "hit");
        h.setAttribute("data-n", n);
        hits.appendChild(h);
    });
    var hot = document.createElementNS(NS, "g");
    D.insts.forEach(function (it, i) {
        if (!it.page) return;
        var r = document.createElementNS(NS, "rect");
        r.setAttribute("x", it.box[0]); r.setAttribute("y", it.box[1]);
        r.setAttribute("width", it.box[2]); r.setAttribute("height", it.box[3]);
        r.setAttribute("class", "hot");
        r.setAttribute("data-i", i);
        var t = document.createElementNS(NS, "title");
        t.textContent = it.name + " : " + it.type + " (click to open)";
        r.appendChild(t);
        hot.appendChild(r);
    });
    function goUp(to) {
        post({ type: "ascend", module: to });
        location.href = encodeURIComponent(to) + ".html";
    }
    (D.ups || []).forEach(function (u) {
        var r = document.createElementNS(NS, "rect");
        r.setAttribute("x", u.at[0] - 2); r.setAttribute("y", u.at[1] - 2);
        r.setAttribute("width", 20); r.setAttribute("height", 20);
        r.setAttribute("class", "hot up");
        r.setAttribute("data-to", u.to);
        var t = document.createElementNS(NS, "title");
        t.textContent = "Collapse " + u.frame + ": back to " + u.to;
        r.appendChild(t);
        hot.appendChild(r);
    });
    var upBtn = document.getElementById("up");
    if (D.ups && D.ups.length) {
        var parentMod = D.ups[D.ups.length - 1].to;
        upBtn.hidden = false;
        upBtn.title = "Back to " + parentMod;
        upBtn.addEventListener("click", function () { goUp(parentMod); });
    }
    var marks = document.createElementNS(NS, "g");
    content.appendChild(hot);
    content.appendChild(hits);
    content.appendChild(marks);

    // ---- pan / zoom ----
    var pz = svgPanZoom(svg, {
        zoomScaleSensitivity: 0.3, dblClickZoomEnabled: false, minZoom: 0.3, maxZoom: 80,
        fit: true, center: true
    });
    // keep the user's view on resize; only re-fit while nothing has moved it yet
    var touched = false;
    svg.addEventListener("wheel", function () { touched = true; }, { passive: true });
    window.addEventListener("resize", function () {
        pz.resize();
        if (!touched) { pz.fit(); pz.center(); }
    });
    document.querySelectorAll(".zoom button").forEach(function (b) {
        b.addEventListener("click", function () {
            var z = b.getAttribute("data-z");
            if (z === "in") pz.zoomIn(); else if (z === "out") pz.zoomOut(); else { pz.fit(); pz.center(); }
        });
    });

    function zoomTo(x, y, w, h) {
        touched = true;
        var cx = x + w / 2, cy = y + h / 2;
        w = Math.max(w, 320); h = Math.max(h, 220);
        var s = pz.getSizes();
        var base = s.realZoom / pz.getZoom();
        var z = Math.min(s.width / (w * 2.2), s.height / (h * 2.2)) / base;
        pz.zoom(Math.max(0.3, Math.min(z, 80)));
        s = pz.getSizes();
        pz.pan({ x: s.width / 2 - cx * s.realZoom, y: s.height / 2 - cy * s.realZoom });
    }
    function flash(x, y, w, h) {
        var r = document.createElementNS(NS, "rect");
        r.setAttribute("x", x - 6); r.setAttribute("y", y - 6);
        r.setAttribute("width", w + 12); r.setAttribute("height", h + 12);
        r.setAttribute("class", "flash");
        marks.appendChild(r);
        setTimeout(function () { r.remove(); }, 3400);
    }
    function instArea(it) {
        return it.box ? it.box : [it.at[0] - 60, it.at[1] - 10, 120, 70];
    }
    function focusInst(name) {
        var it = D.insts.find(function (i) { return i.name === name; });
        if (!it) return false;
        touched = true;
        var a = instArea(it);
        zoomTo(a[0], a[1], a[2], a[3]);
        flash(a[0], a[1], a[2], a[3]);
        return true;
    }

    // ---- net tracing ----
    var panel = document.getElementById("net");
    var current = null;
    function clearNet() {
        if (current === null) return;
        (netPaths.get(current) || []).forEach(function (p) { p.classList.remove("on"); });
        svg.classList.remove("tracing");
        panel.hidden = true;
        current = null;
    }
    function pinText(p) {
        return p[0] ? p[0] + "." + p[1] : "port " + p[1];
    }
    function isDriver(p) { return p[0] ? p[2] === "out" : p[2] === "in"; }
    function selectNet(n) {
        clearNet();
        var net = D.nets[n];
        if (!net) return;
        current = n;
        (netPaths.get(n) || []).forEach(function (p) { p.classList.add("on"); });
        svg.classList.add("tracing");
        var drv = net.pins.filter(isDriver), ld = net.pins.filter(function (p) { return !isDriver(p); });
        var name = (drv[0] || net.pins[0]);
        panel.innerHTML = "";
        var x = el("button", "x", "×"); x.setAttribute("aria-label", "Close"); x.onclick = clearNet;
        panel.appendChild(x);
        panel.appendChild(el("h2", null, name ? pinText(name) : "net " + n));
        panel.appendChild(el("p", "sub", (net.bus ? "bus" : "1-bit") + " · " + net.pins.length + " pins"
            + (drv.length ? "" : " · no driver on this sheet (bus slice or constant)")));
        section("Driven by", drv);
        section("Feeds", ld);
        if (net.taps && net.taps.length) {
            panel.appendChild(el("h3", null, "Bus taps (ripper / bundle)"));
            var ul = el("ul");
            net.taps.forEach(function (t) {
                var o = D.nets[t], lead = o.pins.filter(isDriver)[0] || o.pins[0];
                var b = el("button", null, lead ? pinText(lead) : "net " + t);
                b.appendChild(el("small", null, "  " + (o.bus ? "bus" : "1-bit")));
                b.onclick = function () { selectNet(t); };
                ul.appendChild(el("li")).appendChild(b);
            });
            panel.appendChild(ul);
        }
        panel.hidden = false;
        function section(title, pins) {
            if (!pins.length) return;
            panel.appendChild(el("h3", null, title));
            var ul = el("ul");
            pins.forEach(function (p) {
                var b = el("button", null, pinText(p));
                b.onclick = function () { zoomTo(p[3] - 40, p[4] - 30, 80, 60); flash(p[3] - 12, p[4] - 8, 24, 16); };
                ul.appendChild(el("li")).appendChild(b);
            });
            panel.appendChild(ul);
        }
    }
    function el(tag, cls, text) {
        var e = document.createElement(tag);
        if (cls) e.className = cls;
        if (text != null) e.textContent = text;
        return e;
    }

    // a drag that pans must not count as a click
    var down = null;
    svg.addEventListener("pointerdown", function (e) { down = [e.clientX, e.clientY]; touched = true; });
    svg.addEventListener("click", function (e) {
        if (down && Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 4) return;
        var t = e.target;
        if (t.classList.contains("up")) {
            goUp(t.getAttribute("data-to"));
        } else if (t.classList.contains("hot")) {
            var it = D.insts[+t.getAttribute("data-i")];
            post({ type: "descend", inst: it.name, module: it.type });
            location.href = encodeURIComponent(it.type) + ".html";
        } else if (t.hasAttribute("data-n")) {
            selectNet(+t.getAttribute("data-n"));
        } else {
            clearNet();
        }
    });
    document.addEventListener("keydown", function (e) { if (e.key === "Escape") clearNet(); });

    // ---- search: instances, pins and ports ----
    var index = D.insts.map(function (it) {
        var a = instArea(it);
        return { key: (it.name + " " + it.type).toLowerCase(), area: a };
    });
    var seen = {};
    D.nets.forEach(function (net) {
        net.pins.forEach(function (p) {
            var k = pinText(p);
            if (seen[k]) return;
            seen[k] = 1;
            index.push({ key: k.toLowerCase(), area: [p[3] - 40, p[4] - 30, 80, 60] });
        });
    });
    var q = document.getElementById("q"), hitsOut = document.getElementById("hits");
    var matches = [], at = -1, last = "";
    document.getElementById("find").addEventListener("submit", function (e) {
        e.preventDefault();
        var s = q.value.trim().toLowerCase();
        if (!s) { hitsOut.textContent = ""; return; }
        if (s !== last) {
            last = s; at = -1;
            matches = index.filter(function (m) { return m.key.indexOf(s) !== -1; });
        }
        if (!matches.length) { hitsOut.textContent = "0 found"; return; }
        at = (at + 1) % matches.length;
        var a = matches[at].area;
        zoomTo(a[0], a[1], a[2], a[3]);
        flash(a[0], a[1], a[2], a[3]);
        hitsOut.textContent = (at + 1) + " / " + matches.length;
    });

    // ---- post-synthesis utilization ----
    var U = D.util, statsBtn = document.getElementById("stats"), upanel = document.getElementById("util");
    function fmt(n) { return Number(n).toLocaleString("en-US"); }
    function pct(n, cap) { return cap ? " (" + (100 * n / cap).toFixed(n && 100 * n / cap < 0.1 ? 2 : 1) + "%)" : ""; }
    if (U) {
        var t = U.total, cap = U.device || {};
        statsBtn.hidden = false;
        statsBtn.textContent = fmt(t.lut) + " LUT · " + fmt(t.ff) + " FF" + (t.bram ? " · " + t.bram + " BRAM" : "") + (t.dsp ? " · " + t.dsp + " DSP" : "");
        statsBtn.title = "Post-synthesis utilization of " + U.path + " — click for the breakdown";
        statsBtn.addEventListener("click", function () { upanel.hidden = !upanel.hidden; });
        upanel.innerHTML = "";
        var x = el("button", "x", "\u00d7"); x.setAttribute("aria-label", "Close"); x.onclick = function () { upanel.hidden = true; };
        upanel.appendChild(x);
        upanel.appendChild(el("h2", null, "Synthesized size"));
        upanel.appendChild(el("p", "sub", U.path + " on " + U.part + " · Vivado " + U.tool + " synth_design"));
        var tb = el("table"), head = el("tr");
        ["", "LUT", "FF", "BRAM", "DSP"].forEach(function (h) { head.appendChild(el("th", null, h)); });
        tb.appendChild(head);
        function row(name, r, cls) {
            var tr = el("tr", cls);
            tr.appendChild(el("td", null, name));
            [r.lut, r.ff, r.bram, r.dsp].forEach(function (v) { tr.appendChild(el("td", "n", fmt(Math.round(v * 10) / 10))); });
            tb.appendChild(tr);
        }
        row("this instance", t, "tot");
        U.children.forEach(function (c) { row(c.inst + " : " + c.module, c, null); });
        if (U.children.length) row("rest (this sheet, merged children)", U.own, "own");
        upanel.appendChild(tb);
        upanel.appendChild(el("p", "sub", "Share of the device: " + fmt(t.lut) + pct(t.lut, cap.lut) + " LUT, " + fmt(t.ff) + pct(t.ff, cap.ff) + " FF. "
            + "BRAM counts RAMB36 + RAMB18/2. Small modules are merged into their parent by synthesis and get no row of their own."));
    } else if (D.module !== "TOP") {
        statsBtn.hidden = false;
        statsBtn.disabled = true;
        statsBtn.textContent = "merged by synthesis";
        statsBtn.title = "Synthesis flattened this module into its parent, so it has no utilization row of its own.";
    }

    // ---- parent / deep links ----
    window.addEventListener("message", function (e) {
        var m = e.data || {};
        if (m.type === "theme") {
            if (m.theme === "light" || m.theme === "dark") root.setAttribute("data-theme", m.theme);
            else root.removeAttribute("data-theme");
        } else if (m.type === "focus" && m.inst) {
            focusInst(m.inst);
        }
    });
    var h = /#focus=([^&]+)/.exec(location.hash);
    if (h) requestAnimationFrame(function () { pz.resize(); focusInst(decodeURIComponent(h[1])); });
    post({ type: "ready", module: D.module, chain: D.chain || [], title: document.title });
})();
